export default {
  data() {
    return {
      username: '',
      email: '',
      password: '',
      confirmPassword: ''
    };
  },
  methods: {
    submitForm() {
      if (this.password !== this.confirmPassword) {
        console.error('Passwords do not match');
        return;
      }
      this.$emit('register', {
        username: this.username,
        email: this.email,
        password: this.password
      });
    }
  }
};
